// Material PixelOrdered (@gameengine/materials, compiled; do not edit).
struct MaterialParams {
  p_alphaCutoff: f32,
};
@group(2) @binding(0) var<uniform> material: MaterialParams;
@group(2) @binding(1) var tex_atlas: texture_2d<f32>;
@group(2) @binding(2) var material_sampler: sampler;

fn pixel_srgb_to_linear(c: vec3f) -> vec3f {
 return select(pow((c+vec3f(0.055))/1.055,vec3f(2.4)),c/12.92,c<=vec3f(0.04045));
}

// The atlas is this material's own declared texture binding. Integer loads
// select original mip-zero texels even when the logical canvas shrinks.
fn pixel_load(p: vec2f) -> vec4f { return textureLoad(tex_atlas,vec2i(floor(p)),0); }

const MATERIAL_MODEL: u32 = 1u;
const MATERIAL_FOG: bool = false;
fn material_surface(in: SurfaceInput) -> SurfaceOutput {
  var out = surface_defaults();
  let v0: vec2f = vec2f(2048.0, 1024.0);
  let v1: vec2f = (in.uv * v0);
  let v2: vec4f = pixel_load(v1);
  let v3: vec3f = v2.xyz;
  let v4: vec3f = in.color.xyz;
  let v5: f32 = in.uv.x;
  let v6: f32 = step(v5, -0.5);
  let v7: vec3f = vec3f(v6);
  let v8: vec3f = mix(v3, v4, v7);
  let v9: vec3f = vec3f(0.03137254901960784, 0.047058823529411764, 0.10588235294117647);
  let v10: vec3f = (v8 * 0.09803921568627451);
  let v11: vec3f = (v9 + v10);
  let v12: vec4f = material_global(0u);
  let v13: f32 = v12.z;
  let v14: f32 = in.world_pos.x;
  let v15: f32 = step(108.0, v14);
  let v16: f32 = (v13 * v15);
  let v17: f32 = step(v14, 660.0);
  let v18: f32 = (v16 * v17);
  let v19: f32 = v12.y;
  let v20: f32 = in.world_pos.y;
  let v21: f32 = -(v20);
  let v22: f32 = (v21 + 720.0);
  let v23: f32 = step(v19, v22);
  let v24: f32 = (v18 * v23);
  let v25: f32 = (v19 + 82.0);
  let v26: f32 = step(v22, v25);
  let v27: f32 = (v24 * v26);
  let v28: vec3f = vec3f(v27);
  let v29: vec3f = mix(v8, v11, v28);
  let v30: f32 = v12.x;
  let v31: f32 = -(v30);
  let v32: f32 = (v31 + 1.0);
  let v33: vec3f = (v29 * v32);
  let v34: vec3f = pixel_srgb_to_linear(v33);
  let v35: f32 = v2.w;
  let v36: f32 = mix(v35, 1.0, v6);
  out.base_color = v34;
  out.alpha = v36;
  return out;
}
